        content: "허가사항 \"투여하지 말 것\" 항목 첫 번째는 \"여성 또는 소아\"·\"임부 또는 임신하고 있을 가능성이 있는 여성\"이에요. 부서진 정제 조각은 임부가 만지면 안 돼요. 5α-환원효소 억제제는 테스토스테론의 DHT 전환을 저해해 남성 태아 외부생식기 비정상을 초래할 수 있어요.\n\n4번에는 유당 함유로 인한 \"갈락토오스 불내성·Lapp 유당분해효소 결핍증·포도당-갈락토오스 흡수장애\" 환자 금기가 명시돼 있어요. 일반 유당불내성과는 다른 유전 질환이지만, 우유 섭취 시 심한 증상이 있다면 처방 전 의사 상담이 필요해요. 간 기능 이상 환자는 신중히 투여해야 해요.\n\n피나스테아정 복용 중 헌혈은 금지예요. PCPT 임상시험에서 Gleason 등급 8~10 고등급 전립선암 발생빈도가 위약군 1.1% vs. 약물군 1.8%로 약간 높았어요. 검진 전 반드시 복용 사실을 의사에게 알리고, PSA 수치 두 배 조정을 요청하셔야 해요."
