        content: "피나세트정은 1mg 모발용제 라인의 후발 제네릭이라 오리지널 프로페시아보다 단가가 낮은 편이에요. 같은 1mg 라인 안에서는 다수 제네릭이 있어 약국별 도매 단가에 따라 환자 본인 부담금 차이가 꽤 나는 편이에요.\n\n피나스테리드 1mg 라인은 비급여 처방이 일반적이라 본인이 100% 부담해요. 처방전을 받은 뒤 여러 약국에 단가를 문의하시면 동일 성분·동일 함량 안에서 합리적인 선택이 가능해요. 6년 시판된 후발 라인이라 도매 단가가 일정 수준 안정된 편이에요.\n\n장기 복용 약이라 월 단가 차이가 1년이면 누적이 커요. 같은 1mg 라인 안에서 가격을 비교하시려면 탈모약 비교 페이지에서 1mg 라인을 한눈에 확인하실 수 있어요."
