        content: "피나스타정의 주성분은 피나스테리드 5mg이에요. 식약처 허가사항(품목번호 200200252)에 등록된 분류는 \"기타의 비뇨생식기관 및 항문용약\"으로, 모발용제(탈모용)가 아니에요. 1mg 탈모약과 성분은 같지만 용량이 5배 높아요.\n\n작용 기전은 5α-환원효소 2형 억제예요. 테스토스테론의 DHT 전환을 막아 전립선 조직 DHT 농도를 낮추고, 비대된 전립선이 점차 축소돼요. 효과 판단까지 최소 6개월 이상 복용이 필요해요.\n\n제이더블유중외제약(주)이 2002년 11월에 허가받았어요. 같은 5mg 라인 중 23년 누적 시판된 오래된 라인 중 하나로, 한국MSD 프로스카·피나스정(1995, 30년) 다음 시기 진입한 후발 라인이에요. 같은 라인 중 한국오가논 외 가장 오래된 시판 데이터를 가진 라인이라 시판 후 보고가 풍부한 편이에요."
