    heroDescription: "포뮬레시아정은 식약처 허가사항(피나스테리드 1mg, 모발용제 분류) 기준 만 18~41세 성인 남성의 남성형 탈모증(안드로겐 탈모증) 치료가 적응증인 정제예요. 같은 1mg 모발용제 라인 중 피나스테리드 단일 성분 제네릭으로, 1일 1회 경구 복용·3개월 이상 효과 평가가 동일한 라인이에요. 5α-환원효소 2형을 선택적으로 억제해 두피 DHT를 줄이는 메커니즘이에요.",
