        content: "포뮬레시아정의 주성분은 피나스테리드 1mg이에요. 식약처 허가사항에 등록된 분류는 \"[02670] 모발용제(발모, 탈모, 염모, 양모제)\"로, 5mg(전립선비대증 치료제) 라인과는 분류 자체가 분리돼 있어요.\n\n작용 기전은 5α-환원효소 2형을 선택적으로 억제해, 테스토스테론이 디히드로테스토스테론(DHT)으로 전환되는 과정을 차단하는 거예요. 두피 모낭의 DHT 농도가 낮아지면 위축되던 모낭이 회복기에 접어들고, 모발이 다시 굵어져요.\n\n같은 1mg 모발용제 라인 안에 오리지널 프로페시아(한국오가논)·바로피나정·핀페시아·피나테리정·모나드정·피나세트정·피나테크정 등 다수 제네릭이 있고, 모두 의약품동등성시험을 통과해 약효는 동등해요. 차이는 제조사·도매 채널·약국별 단가예요."
