        content: "피나드정의 주성분은 피나스테리드 5mg이에요. 식약처 허가사항(품목번호 201500591)에 등록된 분류는 \"기타의 비뇨생식기관 및 항문용약\"으로, 모발용제(탈모용)가 아니에요. 1mg 탈모약과 성분은 같지만 용량이 5배 높아요.\n\n작용 기전은 5α-환원효소 2형 억제예요. 테스토스테론의 DHT 전환을 막아 전립선 조직 DHT 농도를 낮추고, 비대된 전립선이 점차 축소돼요. 효과 판단까지 최소 6개월 이상 복용이 필요해요.\n\n(주)이든파마가 2015년 2월에 허가받았어요. 같은 5mg 라인 중 10년 누적 시판된 안정 라인으로, 한국MSD 프로스카(오리지널)·다른 제네릭과 의약품동등성시험을 통과한 라인이에요. 이든파마는 두타엠정(두타스테리드 0.5mg)·피나드정(피나스테리드 5mg) 등 비뇨기과 라인을 다양하게 보유한 회사예요."
