    metaDescription: "두타케어정은 더유제약이 2018년 7월 허가받은 두타스테리드 0.5mg 정제로 7년 누적 시판된 라인이에요. 식약처 허가사항(품목번호 201802827) 기준 양성 전립선비대증과 만 18~50세 남성형 탈모 이중 적응증 정보를 정리했어요.",
    description: "두타케어정은 더유제약 두타스테리드 0.5mg 정제로 7년 시판된 후발 라인이에요. 양성 전립선비대증과 만 18~50세 남성형 탈모 둘 다 적응증이에요.",
