        content: "두타케어정은 두타스테리드 0.5mg 정제 후발 제네릭이라 오리지널 아보다트보다 단가가 낮은 편이에요. 7년 누적 시판된 라인이라 도매 채널이 일정 수준 안정된 편이고, 같은 시기 진입한 두타 정제 라인과 비슷한 가격대에 형성돼 있어요.\n\n탈모 목적 비급여 처방이 일반적이라 본인이 100% 부담해요. 두타스테리드 라인은 피나스테리드 1mg 라인보다 평균 단가가 높은 편이지만, 후발 제네릭은 오리지널 대비 부담이 줄어들어요. 처방전 발급 후 여러 약국에 단가를 문의하시면 합리적이에요.\n\n장기 복용 약이라 월 단가 차이가 1년이면 누적이 커요. 같은 두타스테리드 라인에서 가격을 비교하시려면 탈모약 비교 페이지에서 0.5mg 라인을 확인하실 수 있어요.",
