    h1: "메디녹실액 5% 가격·사용법·부작용 | 동구바이오제약 미녹시딜 5% 외용액 18년 시판 라인",
    metaDescription: "메디녹실액 5%는 (주)동구바이오제약이 2007년 허가받은 미녹시딜 5% 외용액으로 18년 누적 시판된 라인이에요. 식약처 e약은요 정보(품목번호 200710117) 기준 남성형 탈모증 적응증 사용법·부작용을 정리했어요.",
    description: "메디녹실액은 동구바이오제약 미녹시딜 5% 외용액으로 18년 시판된 라인이에요. 남성형 안드로젠 탈모증 적응증이고, 5% 농도라 3% 라인보다 효과는 강하지만 자극도 더 높아요.",
    heroDescription: "메디녹실액 5%는 (주)동구바이오제약이 2007년에 허가받은 미녹시딜 5% 외용액이에요. 식약처 e약은요 정보(품목번호 200710117) 기준 \"남성형 탈모증의 치료\"에 사용하는 외용 도포액이고, 18년 누적 시판된 라인이에요. 5% 농도라 3% 라인(나녹시딜액3·마이녹실액 등) 대비 미녹시딜 농도가 더 높아 효과는 강하지만 두피 자극·다모증 부작용 빈도도 함께 올라가요. 동구바이오제약은 두타리드연질캡슐(2022)도 보유한 회사예요.",
    products: [],
