        content: "백일후애캡슐은 6년 시판된 동광제약 모발 영양 복합 라인이에요. 같은 적응증을 가진 다른 일반의약품 라인(판토가·카필러스·모앤캡슐·볼두민캡슐·모나에스캡슐 등)과 비슷한 가격대에 형성돼 있어요. 일반의약품이라 처방전 없이 약국에서 구매 가능하고, 본인이 100% 부담해요.\n\n탈모 1차 치료 라인(피나스테리드·두타스테리드·외용 미녹시딜)과는 가격대가 직접 비교되지 않는 별개 라인이에요. 영양 보조 목적이라 1차 치료제보다는 단가가 낮은 편이지만, 1일 3회 복용으로 월 사용량이 많아 누적 비용이 1차 치료제와 비슷할 수 있어요.\n\n같은 적응증의 영양 보조 라인끼리 가격을 비교하시려면 탈모약 비교 페이지에서 \"탈모의 보조치료\" 라인을 한눈에 확인하실 수 있어요. 약국별 단가에 따라 차이가 있으니 직접 문의해 보세요.",
