    heroDescription: "그로모정은 (주)에이프로젠바이오로직스가 2006년 12월에 허가받은 피나스테리드 1mg 정제예요. 식약처 허가사항(품목번호 200701016)에 등록된 분류는 \"[02670] 모발용제\"이고, 만 18~41세 남성형 탈모증이 단일 적응증으로 등록된 19년 시판 안정 라인이에요. 같은 시기에 자리잡은 1mg 라인(피나모린정 태극제약 2006·헤어페시아정 동화약품 2006) 그룹과 함께 가장 오래된 시판 라인 중 하나예요.",
