    heroDescription: "페로시아정은 (주)유한양행이 2007년 4월에 허가받은 피나스테리드 1mg 정제예요. 식약처 허가사항(품목번호 200704535)에 등록된 분류는 \"[02670] 모발용제\"이고, 만 18~41세 남성형 탈모증이 단일 적응증으로 등록된 18년 시판 안정 라인이에요. 유한양행은 국내 대표 제약사 중 하나로, 도매 채널이 가장 광범위하게 안정된 1mg 라인 중 하나예요. 같은 시기 진입한 1mg 라인(메디페시아정 고려제약 2007.12·베아리모정 대웅제약 2007.07)과 비슷한 시점에 자리잡은 안정 라인이에요.",
