        content: "핀스타정은 5mg 전립선비대증 치료제 라인이라 1mg 탈모약 라인과 가격을 직접 비교하기 어려워요. 5mg 라인 안에서 보면 2013년 허가 후 12년 누적 시판된 라인이라 도매 단가가 안정된 편이에요.\n\n같은 5mg 라인 중 한국오가논 피나스정(1995, 30년) 등 오리지널 라인 대비 후발 제네릭이라 단가가 낮은 편이에요. 보험 적용 여부에 따라 본인부담금이 달라지니 처방전 발급 후 가까운 약국 두세 곳에 단가를 문의하시면 합리적이에요.\n\n탈모 목적으로 가격을 비교하시려면 1mg 라인을 따로 살펴보셔야 해요. 같은 성분이지만 시판 라인이 분리되어 있고, 5mg 분할 복용은 허가사항에서 금지된 데다 임산부 접촉 위험으로도 권장되지 않아요.",
