        content: "피나스틴정의 주성분은 피나스테리드(Finasteride) 5mg이에요. 식약처 허가사항 품목번호 200300392 기준이고, 부광약품(주)이 2003년 3월에 신고한 전문의약품이에요. 적응증은 양성전립샘비대증 치료로, 1mg 탈모 치료제 라인과는 별개의 카테고리예요.\n\n피나스테리드는 5알파환원효소 2형을 선택적으로 억제하는 성분이에요. 테스토스테론이 DHT(디하이드로테스토스테론)로 전환되는 걸 막아 전립샘 내 DHT 농도를 낮춰요. 5mg 용량은 전립샘 자체의 크기를 줄이는 데 초점이 맞춰져 있고, 그 결과로 요도 압박이 풀리면서 배뇨 증상이 개선돼요.\n\n부광약품은 5mg 피나스테리드 시장에 2003년 진입한 라인이라 22년 누적 시판 이력을 갖고 있어요. 같은 5mg 라인 중 한국오가논 피나스정(1995, 30년) 다음으로 일찍 진입한 그룹에 속하고, 하나제약 푸로케어정(2005, 20년)이나 유한양행 파나스카정(2005, 20년)보다도 시판 연혁이 길어요. 1mg 탈모용 라인을 찾으시는 분이라면 처방 시점에서 명확히 의사에게 말씀하셔야 해요.",
