        content: "피나스틴정은 5mg 전립샘비대증 치료제 라인이라 1mg 탈모약과 단가를 직접 비교하기 어려워요. 5mg 라인 안에서 보면 2003년 3월 신고 후 22년 누적 시판된 라인이라 도매 채널이 광범위하게 안정된 편이에요. 같은 5mg 라인 중 한국오가논 피나스정(1995, 30년) 다음으로 가장 오래된 시판 라인 중 하나예요.\n\n부광약품은 국내 중견 제약사 중 하나라 약국별 단가 편차도 비교적 적은 편이에요. 22년 누적 시판 라인이라 처방 의사 사이에서 인지도도 높고, 보험 적용 여부에 따라 본인부담금이 달라지니 처방전 발급 후 가까운 약국 두세 곳에 단가를 문의하시면 합리적이에요.\n\n탈모 목적으로 가격을 비교하시려면 1mg 모발용제 라인을 따로 살펴보셔야 해요. 5mg을 쪼개 1mg으로 복용하는 건 정제 코팅이 손상되면서 임산부 노출 위험이 생겨 권장되지 않아요.",
