    metaDescription: "프로다트연질캡슐 제뉴원사이언스 두타스테리드 0.5mg 연질캡슐 정보. BPH와 18~50세 남성형 탈모 두 적응증. 2016년 허가 9년차 라인. 식약처 허가사항 기반 효과·복용법·부작용·가격 안내.",
    description: "프로다트연질캡슐은 주식회사제뉴원사이언스 두타스테리드 0.5mg 연질캡슐이에요 (품목번호 201601191). 제품명 \"프로(prostate)\"가 BPH 처방 시장을 겨냥한 라인임을 보여주고, 18~50세 남성형 탈모도 적응증에 등록돼 있어요.",
