        content: "프로다트연질캡슐의 주성분은 두타스테리드(Dutasteride) 0.5mg이에요. 식약처 허가사항 품목번호 201601191 기준이고, 주식회사제뉴원사이언스가 2016년 2월에 허가받은 전문의약품이에요. 제품명에 \"프로(prostate)\"가 들어간 만큼 BPH 처방 시장을 1차 타겟으로 마케팅된 라인이에요.\n\n두타스테리드는 5알파환원효소 1형과 2형을 모두 억제하는 성분이에요. 피나스테리드가 2형만 억제하는 것과 달리 1형까지 차단하기 때문에, 같은 0.5mg 1일 1회 복용에서 DHT 감소 폭이 더 커요. 식약처 허가사항에 BPH 증상 개선·요저류 위험성 감소·수술 필요성 감소가 적혀 있고, 동일 항목에 \"성인 남성(만 18~50세)의 남성형 탈모(androgenetic alopecia)의 치료\"가 명시돼 있어요.\n\n같은 두타스테리드 0.5mg 제네릭 라인 중 프로다트는 2016년 2월에 진입한 그룹이에요. 같은 시기 그룹으로 (주)씨티씨바이오 유로다트연질캡슐(2016.06)이 있고, 둘 다 제품명에 \"다트\"가 들어가 BPH 처방을 겨냥한 명명 패턴이 비슷해요. 선발 그룹인 광동제약 두아보연질캡슐(2014.12)이나 (주)대웅제약 두타겟연질캡슐(2015.10)보다는 약간 늦게 진입했어요.",
