    h1: "타테린연질캡슐 가격 효과·부작용 | 비보존제약 두타스테리드 0.5mg (BPH+탈모, 8년차 후발 라인)",
    metaDescription: "타테린연질캡슐 (주)비보존제약 두타스테리드 0.5mg 연질캡슐 정보. BPH와 18~50세 남성형 탈모 두 적응증. 2017년 허가 후발 라인. 식약처 허가사항 기반 효과·복용법·부작용·가격 안내.",
    description: "타테린연질캡슐은 (주)비보존제약 두타스테리드 0.5mg 연질캡슐이에요 (품목번호 201706885). 비보존제약은 비마약성 진통제 \"오피란제린\" 개발사로 알려진 회사이고, BPH와 18~50세 남성형 탈모 두 적응증이 있어요.",
