        content: "타테린연질캡슐의 주성분은 두타스테리드(Dutasteride) 0.5mg이에요. 식약처 허가사항 품목번호 201706885 기준이고, (주)비보존제약이 2017년 8월에 허가받은 전문의약품이에요. 비보존제약은 비마약성 진통제 \"오피란제린\" 개발로 알려진 중견 제약사로, 같은 두타스테리드 0.5mg 라인 중 후발 그룹에 속해요.\n\n두타스테리드는 5알파환원효소 1형과 2형을 모두 억제하는 성분이에요. 피나스테리드가 2형만 억제하는 것과 달리 1형까지 차단하기 때문에, 같은 0.5mg 1일 1회 복용에서 DHT 감소 폭이 더 커요. 식약처 허가사항에 BPH 증상 개선·요저류 위험성 감소·수술 필요성 감소가 적혀 있고, 동일 항목에 \"성인 남성(만 18~50세)의 남성형 탈모(androgenetic alopecia)의 치료\"가 명시돼 있어요.\n\n같은 두타스테리드 0.5mg 제네릭 라인 중 타테린은 2017년 8월에 진입한 후발 그룹이에요. 선발 그룹인 광동제약 두아보연질캡슐(2014.12), (주)대웅제약 두타겟연질캡슐(2015.10)보다 약 2~3년 늦게 진입했고, 가장 후발인 구주제약 듀타그렌정(2018.10)보다는 약간 일찍 진입했어요.",
