                "answer": "1일 2회·0.5~1mL/회·총 2mL 한도가 식약처 허가사항 기준이에요. 1회로 줄이면 표준 평가 기준에서 벗어나 4개월 시점에 \"효과 없음\"으로 결론 내리기 어려워요. 직장 일과상 2회가 부담되시면 아침 1회·저녁 1회 패턴 자체를 바꾸기보다 양 0.5mL로 맞추고 횟수를 유지하는 쪽이 평가에 합리적이에요."
