        content: "모바린액은 OTC 일반의약품이지만 사용 금기 환자군이 명확해요. 식약처 허가사항이 절대 금기로 정한 그룹은 1) 미녹시딜 또는 약 성분에 과민증 환자, 2) 여성 환자, 3) 18세 미만 환자, 4) 심혈관계 질환자(관상동맥·부정맥·울혈심부전·심장판막·고혈압·저혈압), 5) 유전적 요인 없는 탈모·갑작스런 부분 탈모·두피 이상(홍반·염증·감염·자극·건선·일광화상)·원인 불명 탈모·두피 면도 환자, 6) 2% 농도에 내약성 좋지 않은 환자예요.\n\n약국에서 모바린액을 셀프 구매할 때 약사가 가장 먼저 확인하는 항목이 심혈관 질환 병력이에요. 미녹시딜 외용제는 두피에서 일부 흡수되어 혈관 확장 효과를 낼 수 있고, 고혈압약·심장약을 복용 중인 분이 추가로 모바린액을 쓰면 혈압이 예상치 못하게 떨어지거나 심박이 빨라질 수 있어요. 50대 이상 OTC 환자는 모바린액 시작 전 혈압·심박 체크를 기록해 두시면 부작용 모니터링에 도움이 돼요.\n\n사용 시 주의 항목으로 고령자, 부종, 갑상샘기능장애(저하증·항진증), 프로필렌글리콜 과민 경험자는 약사·의사 상담이 필요하다고 명시돼 있어요. 모바린액은 외용 전용이라 두피 이외 부위 도포 금지, 밀봉붕대법 금지, 구아네티딘 등 혈관확장제 병용 금지가 식약처 허가사항에 적혀 있어요.",
