    metaDescription: "마이녹실겔 현대약품 마이녹실 브랜드 미녹시딜 5% 겔 정보. 마이녹실액 자극 환자가 같은 브랜드 안에서 갈아탈 수 있는 겔 라인. 자극 민감자 첫 시작 옵션. 18년 시판.",
    description: "마이녹실겔은 현대약품의 마이녹실 브랜드 미녹시딜 5% 겔이에요 (품목번호 200712998). 한국 외용 미녹시딜 시장의 메이저 브랜드인 마이녹실 라인 안에서, 액제 자극을 호소하는 환자가 같은 회사·같은 농도로 갈아탈 수 있도록 2007년 12월에 출시된 겔 제형이에요.",
    heroDescription: "마이녹실겔은 현대약품(주)이 2007년 12월에 허가받은 마이녹실 브랜드의 겔 제형 미녹시딜 5%예요. 마이녹실액(액제)을 4개월 평가 도중 자극으로 중단할 뻔했던 OTC 환자들이 같은 브랜드·같은 5% 농도 그대로 갈아탈 수 있는 겔 라인이라, 한국 외용 미녹시딜 시장에서 \"액제→겔\" 전환의 표준 경로로 자리 잡은 라인이에요. 18년 시판 누적이에요.",
