        title: "마이녹실겔 효과가 나타나려면 얼마나 걸리나요?",
        content: "마이녹실겔의 식약처 허가 적응증은 \"남성형 탈모증(안드로젠탈모증)의 치료\"예요. 액제와 동일한 적응증이고, 효과 평가의 표준 시점도 4개월로 같아요. 18년 시판 데이터에서 마이녹실겔로 4개월 평가를 완주한 환자가 액제 환자보다 \"중도 자극으로 중단\" 비율이 낮은 게 겔 라인의 실용 이점이에요.\n\n초기 1~2개월의 휴지기 탈락(shedding) 현상은 액제·겔 모두 동일해요. 미녹시딜이 모낭의 모발 주기를 휴지기에서 성장기로 강제 전환시키는 과정에서 휴지기 모발이 한꺼번에 빠지고 새 성장기 모발이 자라나는 거라, 이 시점에 \"마이녹실액보다 마이녹실겔이 더 빠지는 것 같다\" 느낌은 자극이 아니라 약효의 일부예요. 겔로 갈아탔다고 이 과정이 사라지지 않아요.\n\n4개월 시점 사진 비교가 평가 기준이에요. 정수리·앞머리(M자) 부위를 같은 조명·각도로 시작 시점과 4개월 시점에 촬영해 비교하시면 미세한 변화도 확인할 수 있어요. 효과가 나타나면 멈추지 마세요. 중단 시 3~6개월 안에 원래 상태로 돌아가요. 사용 중단으로 효과가 사라지는 패턴은 액제·겔 모두 동일해요.",
