    h1: "모바린겔 가격 효과·부작용 | 일화 모바린 브랜드 5% 겔 (모바린액→겔 자매 전환, 부형제 단일 변수 통제)",
    metaDescription: "모바린겔 (주)일화 모바린 브랜드 미녹시딜 5% 겔 정보. 같은 회사 모바린액에서 갈아탈 때 회사·생산 공정 변수 없이 부형제만 단일 변수로 통제할 수 있는 자매 라인.",
    description: "모바린겔은 (주)일화의 모바린 브랜드 미녹시딜 5% 겔 라인이에요. 같은 회사 모바린액(액제)을 4개월 평가 도중 자극으로 중단할 뻔했던 환자가 같은 회사·같은 농도로 갈아탈 수 있도록 출시된 자매 제형이에요.",
    heroDescription: "모바린겔은 (주)일화가 만든 미녹시딜 5% 외용 겔이에요. 같은 회사 모바린액과 자매 라인이라 액제→겔 전환 시 회사·생산 공정·유통 채널 변화 없이 부형제(에탄올·프로필렌글리콜)만 단일 변수로 바뀌는 게 핵심이에요. \"자극 원인이 부형제인지 미녹시딜 자체인지\"를 가리고 싶을 때 같은 회사 라인 안에서 갈아타는 게 가장 진단적이에요.",
