                "question": "모바린액과 모바린겔을 동시에 사용하면 효과가 두 배로 나오나요?",
                "answer": "절대 안 돼요. 두 라인 모두 미녹시딜 5%라 동시 사용 시 1일 한도(2mL/2g) 초과로 미녹시딜이 누적 흡수돼 전신 부작용 위험(혈압 변화·심박 증가·하지 부종·체중 증가)이 급격히 커져요. 식약처 허가사항도 \"다른 두피용 약물과 함께 사용 금지\"를 명시하고 있어요. 갈아탈 때는 모바린액을 완전히 중단한 뒤 모바린겔로 전환해야 해요."
