        content: "하이녹실정은 피나스테리드 1mg 필름코팅 정제예요. 식약처 허가사항이 분류한 카테고리는 모발용제(02670)이고, 같은 분류에 오리지널 프로페시아(MSD)와 다수의 1mg 제네릭 라인이 함께 등재돼 있어요. 캡슐 제형 라인(케라탑캡슐·모싱싱캡슐 등)과 다른 정제 제형이라 외형부터 식별이 명확해요.\n\n주성분 피나스테리드는 5알파환원효소 2형을 선택적으로 억제해 테스토스테론이 DHT(디하이드로테스토스테론)로 전환되는 걸 막는 성분이에요. 식약처 허가사항에 따르면 1mg 1일 1회 복용 시 두피 모낭 주변 DHT 농도를 효과적으로 낮춰 모낭 위축을 막고 모발 굵기를 회복시키는 작용을 해요. 정제를 부수면 안 된다는 룰은 캡슐 라인과 같지만, 정제는 분말 노출 시 코팅 파편까지 흩어지는 패턴이라 더 광범위하게 청소해야 해요.\n\n정제 외피는 필름코팅이라는 점이 핵심이에요. 코팅된 정제는 정상 운반·보관 환경에서 주성분이 외부로 노출되지 않아 임신 가능 여성·수유부와 동거 중인 환자가 약을 식탁·서랍·약통에 보관해도 비교적 안전해요. 캡슐 라인은 캡슐 외피가 손상되면 분말이 새어나오는 위험이 있는 반면, 코팅 정제는 외피 손상이 더 명확히 눈에 보여 폐기 판단이 쉬워요.",
