        content: "하이녹실정의 식약처 허가 적응증은 \"성인남성(만 18~41세)의 남성형 탈모증(안드로겐 탈모증)의 치료\" 단일 항목이에요. 41세 초과 남성은 허가 범위 밖이라 처방 시 의사가 환자 연령을 확인해요. 정수리(두정부)와 M자 이마 부위의 탈모 진행을 억제하고 모발 밀도를 높이는 효과가 임상에서 확인됐어요.\n\n임상 데이터에 따르면 효과 판정 표준은 3개월 이상 지속 복용이에요. 1~2개월차에 모발이 더 빠지는 듯한 \"shedding\"은 모낭이 휴지기에서 성장기로 강제 전환되는 정상 과정이라, 이 시점에 중단하면 평가 자체가 무산돼요. 6~12개월 시점에서 두정부 사진 비교가 효과 평가의 표준 방법이에요.\n\n복용을 중단하면 12개월 이내에 치료 효과가 사라지고 탈모가 재진행돼요. 캡슐 라인이든 정제 라인이든 동일한 패턴이에요. 하이녹실정은 여성형 탈모, 원형 탈모, 출산 후 탈모에는 효과가 없어요. 갑자기 모발이 빠지기 시작했다면 자가 시도 전에 피부과·내과에서 탈모 유형부터 진단받으셔야 해요.",
