        content: "바이모정은 (주)바이넥스의 미녹시딜 5mg 경구 정제예요. 식약처 허가사항 품목번호 201908280으로 2019년 12월에 신고된 라인이고, 카테고리는 [02140]혈압강하제예요. 바이넥스는 부산 본사를 둔 국내 중견 제약사로 합성의약품 CMO·CDMO 사업이 강점이고, 미녹시딜 카테고리에서는 같은 회사가 단백아미노산 보조치료 라인(유나모캡슐, 2017년)도 함께 보유해요.\n\n주성분 미녹시딜은 세동맥 평활근에 직접 작용하는 강력한 말초혈관 확장제예요. 경구로 들어가면 전신 혈관이 확장돼 혈압을 빠르게 낮추는데, 이 작용 강도가 일반 혈압약(ACE 억제제·ARB·칼슘차단제)보다 압도적이라 \"다른 혈압약 다 듣지 않는 환자\"에게만 사용하는 최후 수단 라인이에요.\n\n바이모정과 같은 카테고리 후발 라인으로 (주)인트로바이오파마 인트로미녹시딜정(2021), (주)메디카코리아 메디카미녹시딜정(2021), 대한뉴팜 대한뉴팜미녹시딜정(2021) 등이 있어요. 모두 같은 미녹시딜 5mg 성분·같은 적응증이지만 회사·시판 연혁이 다른 동일 카테고리 라인들이고, 처방 시 의사가 도매·재고 사정에 따라 라인을 선택해요.",
