    h1: "대한뉴팜미녹시딜정 가격 효과·부작용 | 대한뉴팜 미녹시딜 외용 (남성+여성 탈모 두 적응증, 2021년 라인)",
    metaDescription: "대한뉴팜미녹시딜정 대한뉴팜 미녹시딜 5% 외용 정보. 식약처 허가사항에 남성형+여성형 탈모증 두 적응증이 등재된 2021년 라인. 같은 시기 메디카미녹시딜정과 자매 라인 관계.",
    description: "대한뉴팜미녹시딜정은 대한뉴팜(주) 미녹시딜 5% 외용제예요 (품목번호 202104812). 식약처 허가사항에 남성형 탈모증과 여성형 탈모증 두 적응증이 모두 등재된 2021년 6월 신고 라인이고, 같은 시기 출시된 메디카미녹시딜정과 적응증·사용법이 거의 같아요.",
