        content: "케라스트캡슐은 세 가지 효능이 허가돼 있어요. 첫째, 손상된 모발의 회복이에요. 잦은 펌이나 염색, 자외선 노출 등으로 손상된 모발에 영양을 공급해서 건강한 상태로 회복시켜줘요.\n\n둘째, 탈모의 보조 치료예요. 미만성 탈모(머리 전체적으로 모발이 가늘어지고 밀도가 줄어드는 유형)에 효과적이에요. 단, 흉터로 인한 탈모, 안드로젠 유전성 탈모증(남성형 대머리)에는 효과가 없어요.\n\n셋째, 감염성이 아닌 손톱의 발육 부진 개선이에요. 손톱이 잘 부러지거나 갈라지는 증상에도 개선 효과가 있어요. 평균 치료 기간은 3~6개월이며, 3~4개월 사용 후에도 증상 개선이 없으면 복용을 중단하고 의사와 상담하세요.",
