        content: "케라스트캡슐은 성인 1회 1캡슐을 1일 3회, 식후에 물과 함께 복용해요. 캡슐을 통째로 삼키세요. 열어서 내용물만 먹거나 씹으면 약효가 제대로 발휘되지 않아요.\n\n12세 이상 소아는 1회 1캡슐을 1일 1~2회 식후에 복용해요. 12세 미만은 복용하면 안 돼요. 공복에 복용하면 위장 불편감이 생길 수 있으니 식사 후에 복용하는 게 중요해요.\n\n아침, 점심, 저녁 식후에 1캡슐씩 규칙적으로 나눠 복용하면 흡수율이 높아요. 한 끼를 놓쳤다면 다음 복용 시 2캡슐을 먹지 말고 1캡슐만 먹으세요. 맥널티제약(주)의 케라스트캡슐 평균 치료 기간은 3~6개월이에요.",
