        content: "케라스트캡슐은 단백아미노산 복합 보조치료 라인이라 같은 보조치료 라인끼리 비교하는 게 의미가 있어요. 식약처 허가사항 품목번호 200905074 기준 2009년 5월 허가 후 16년 시판된 라인으로, 같은 단백아미노산 보조치료 라인 중 가장 오래된 시판 그룹에 속해요. 후발 라인인 동화약품 케라티딘(2019), 시어스제약 모나그린(2020), 원광 마이시딜(2020)에 비해 10년 이상 시판 연혁이 길어요.\n\n보조치료 라인이라 정공 탈모 치료제(1mg 피나스테리드·외용 미녹시딜)와는 약가 체계가 달라요. 처방 사유에 따라 보험 적용 여부가 달라지니 약국에 단가를 확인해 보세요. 맥널티제약 라인은 시판 연혁이 길어 약국 도매·인지도가 비교적 안정된 편이에요.\n\n같은 \"케라\" 명칭을 가진 케라탑캡슐(피나스테리드 1mg)과는 다른 카테고리이니 처방 시 혼동하면 안 돼요. 정공 탈모 처방을 찾으시는 분은 1mg 피나스테리드 라인이나 미녹시딜 외용제를 1차로 검토하셔야 해요.",
